import { test, expect } from '@playwright/test';

test.describe('Search Filter Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should exclude a term when prefixed with "-"', async ({ page }) => {
    await page.fill('input[name="search"]', 'apple -banana');
    await page.click('button[type="submit"]');

    const results = await page.locator('.search-results'); // Adjust selector as needed
    await expect(results).toContainText('apple');
    await expect(results).not.toContainText('banana');
  });

  test('should return results when no exclusion term is used', async ({ page }) => {
    await page.fill('input[name="search"]', 'apple');
    await page.click('button[type="submit"]');

    const results = await page.locator('.search-results'); // Adjust selector as needed
    await expect(results).toContainText('apple');
  });
});
